//	}
func (m *MaskerMarshaler) Struct(s interface{}) (interface{}, error) {
	if s == nil {
		return nil, fmt.Errorf("input is nil")
	}

	var selem, tptr reflect.Value

	st := reflect.TypeOf(s)
	sv := reflect.ValueOf(s)

	actualKind := st.Kind()
	if actualKind == reflect.Ptr {
		if sv.IsNil() {
