package masker

import "testing"

// benchAccount 為 benchUser 的巢狀 struct 欄位，供 benchmark 觀察巢狀 type 亦受惠於 cache。
type benchAccount struct {
	Name   string `mask:"name"`
	Email  string `mask:"email"`
	ID     string `mask:"id"`
	Mobile string `mask:"mobile"`
}

// benchUser 模擬真實 API 記錄：少數 PII 欄位（需遮罩）搭配多個非敏感 metadata 欄位（直接複製）+ 一個巢狀 struct。
// 此分布反映典型 DTO（PII 只佔少數），讓 cache 省下的成本（cold 每次須對「全部」欄位 parse tag）
// 相對於 warm 每次僅遮罩少數欄位的成本更具代表性，避免「全 PII」這種對 cache 最不利的極端 case 失真。
type benchUser struct {
	// PII 欄位（需遮罩）
	Name     string `mask:"name"`
	Email    string `mask:"email"`
	Password string `mask:"password"`
	ID       string `mask:"id"`
	Mobile   string `mask:"mobile"`
	Credit   string `mask:"credit"`

	// 非敏感 metadata（無 tag，直接複製）
	Age        int
	Active     bool
	Score      float64
	Level      int
	LoginCount int
	Verified   bool
	CreatedAt  string
	UpdatedAt  string
	Country    string
	Language   string
	Timezone   string
	Status     string

	Account benchAccount `mask:"struct"`
}

func benchFixture() benchUser {
	return benchUser{
		Name:       "John Doe",
		Email:      "john@gmail.com",
		Password:   "password",
		ID:         "A123456789",
		Mobile:     "0912345678",
		Credit:     "4111111111111111",
		Age:        30,
		Active:     true,
		Score:      98.5,
		Level:      7,
		LoginCount: 142,
		Verified:   true,
		CreatedAt:  "2024-01-02T03:04:05Z",
		UpdatedAt:  "2025-06-23T10:00:00Z",
		Country:    "TW",
		Language:   "zh-TW",
		Timezone:   "Asia/Taipei",
		Status:     "active",
		Account: benchAccount{
			Name:   "Jane Doe",
			Email:  "jane@gmail.com",
			ID:     "B223456789",
			Mobile: "0987654321",
		},
	}
}

// BenchmarkStruct 量測 cache warm 後對同一 type 反覆呼叫 Struct() 的穩態開銷。
func BenchmarkStruct(b *testing.B) {
	m := NewMaskerMarshaler()
	in := benchFixture()
	resetTypeCache()
	if _, err := m.Struct(in); err != nil { // warm cache
		b.Fatal(err)
	}
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_, _ = m.Struct(in)
	}
}

// BenchmarkStructCold 每次 iteration 先清空 cache 再呼叫 Struct()，代表含 tag 解析的冷路徑。
func BenchmarkStructCold(b *testing.B) {
	m := NewMaskerMarshaler()
	in := benchFixture()
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		resetTypeCache()
		_, _ = m.Struct(in)
	}
}

// BenchmarkFormat 量測對同一 type 反覆呼叫 Format() 直出遮罩字串的開銷。
func BenchmarkFormat(b *testing.B) {
	m := NewMaskerMarshaler()
	in := benchFixture()
	resetTypeCache()
	_ = m.Format(in) // warm cache
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_ = m.Format(in)
	}
}

